// Evidence annotations and reproducible VM-based report builder for TaskView #43.
const fs = require('node:fs');
const vm = require('node:vm');
const path = require('node:path');
const root = path.resolve(__dirname, '../..');
const data = {};
for (const [kind, file, symbol] of [['grant','grants','GRANTS_DIRECTORY'],['org','orgs','ORGS_DIRECTORY']]) {
  const context = vm.createContext({});
  vm.runInContext(fs.readFileSync(path.join(root, `public/${file}-data.js`), 'utf8') + `\nresult = ${symbol};`, context);
  data[kind] = JSON.parse(JSON.stringify(context.result));
}
const audits = [];
let current;
function entry(kind,id) {
 const record=data[kind].find(r=>r.id===id); if(!record) throw Error(id);
 const source=`${kind}-${id}.txt`;
 const text=fs.readFileSync(path.join(__dirname,'dir-snapshots',source),'utf8');
 current={kind,id,record,source,text,rows:[]}; audits.push(current);
}
function row(field,assertion,status,quote='',note='') {
 for(const q of quote.split(' ⟂ ').filter(Boolean)) if(!current.text.includes(q)) throw Error(`Quote not found: ${current.id}: ${q}`);
 current.rows.push({field,assertion,status,quote,note});
}
const C=(f,a,q)=>row(f,a,'CONFIRMED',q);
const N=(f,a)=>row(f,a,'NOT ON PAGE');
const D=(f,a,q,n)=>row(f,a,'DIFFERS',q,n);
// Concrete factual assertions are separated even when they share a source quote.
