const fixes=[];
function fix(kind,id,field,old,quote) {
 const audit=audits.find(a=>a.kind===kind && a.id===id);
 for(const q of quote.split(' ⟂ ')) if(!audit.text.includes(q)) throw Error(`Invalid fix evidence ${id}: ${q}`);
 fixes.push({kind,id,field,old,value:audit.record[field],quote});
}
